#!/usr/bin/env python3
"""
BFS Bot v2 — Self-extracting codebase pack.
Run this script to recreate the full project on this machine.

Usage:
  python bfs_bot_pack.py              # Unpack to current directory
  python bfs_bot_pack.py --output /path/to/dest
"""

import argparse
import base64
from pathlib import Path


def unpack(dest: Path) -> None:
    dest = dest.resolve()
    dest.mkdir(parents=True, exist_ok=True)
    for rel_path, b64_content in FILES.items():
        out = dest / rel_path
        out.parent.mkdir(parents=True, exist_ok=True)
        content = base64.b64decode(b64_content).decode("utf-8")
        out.write_text(content, encoding="utf-8")
        print(f"  Created: {rel_path}")
    print(f"\nDone. Project extracted to {dest}")


